<?php

use App\Http\Controllers\Api\AppHadithSourceController as HadithSources;
use App\Http\Controllers\Api\AppLocalizationController as Content;
use App\Http\Controllers\Api\AppSessionController as Session;
use App\Http\Controllers\Api\AppSourceController as Sources;
use App\Http\Controllers\Api\NearbyMosquesController;
use App\Http\Middleware\AppAccountOnly;
use App\Http\Middleware\AppAdminOnly;
use App\Http\Middleware\ReligiousAccountOnly;
use Illuminate\Support\Facades\Route;

Route::prefix('v2')->middleware('throttle:60,1')->group(function (): void {
    Route::post('mosques/nearby', NearbyMosquesController::class)->middleware('throttle:10,1,mosques');
    Route::post('account/login', [Session::class, 'login'])->middleware('throttle:10,1');
    Route::post('account/exchange', [Session::class, 'exchange'])->middleware(['auth:sanctum', ReligiousAccountOnly::class]);
    Route::middleware(['auth:sanctum', AppAccountOnly::class])->group(function (): void {
        Route::get('account/session', [Session::class, 'current']);
        Route::post('account/logout', [Session::class, 'logout']);
        Route::post('account/link', [Session::class, 'link'])->middleware('throttle:5,1');
        Route::post('admin/session', [Session::class, 'admin']);
        Route::get('association/profile', [\App\Http\Controllers\Api\AssociationProfileController::class, 'show']);
        Route::put('association/profile', [\App\Http\Controllers\Api\AssociationProfileController::class, 'update']);
        Route::post('association/profile/transfers', [\App\Http\Controllers\Api\AssociationProfileController::class, 'startTransfer']);
        Route::get('association/invitations', [\App\Http\Controllers\Api\AssociationInvitationsController::class, 'index']);
        Route::get('association/invitations/{invitation}', [\App\Http\Controllers\Api\AssociationInvitationsController::class, 'show'])->whereNumber('invitation');
        Route::post('association/invitations/{invitation}/action', [\App\Http\Controllers\Api\AssociationInvitationsController::class, 'action'])->whereNumber('invitation');
        Route::post('association/devices', [\App\Http\Controllers\Api\AssociationDevicesController::class, 'register']);
        Route::post('association/heartbeat', [\App\Http\Controllers\Api\AssociationDevicesController::class, 'heartbeat'])->middleware('throttle:30,1');
        Route::get('association/conversations/{module}', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'index'])->whereIn('module', ['chat', 'support']);
        Route::get('association/chat/contacts', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'contacts']);
        Route::post('association/chat/start', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'ownerStart']);
        Route::get('association/support/categories', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'supportCategories']);
        Route::post('association/support/start', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'openSupport']);
        Route::get('association/threads/{thread}', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'show'])->whereNumber('thread');
        Route::post('association/threads/{thread}/messages', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'send'])->whereNumber('thread');
        Route::post('association/threads/{thread}/presence', [\App\Http\Controllers\Api\AssociationConversationsController::class, 'presence'])->whereNumber('thread');
        Route::post('association/threads/{thread}/transfers', [\App\Http\Controllers\Api\AssociationTransfersController::class, 'threadStart'])->whereNumber('thread');
        Route::get('association/inbox', [\App\Http\Controllers\Api\AssociationNotificationsController::class, 'inbox']);
        Route::get('association/inbox/{notification}', [\App\Http\Controllers\Api\AssociationNotificationsController::class, 'inboxShow'])->whereNumber('notification');
        Route::post('association/inbox/{notification}/acknowledge', [\App\Http\Controllers\Api\AssociationNotificationsController::class, 'acknowledge'])->whereNumber('notification');
        Route::get('association/forms', [\App\Http\Controllers\Api\AssociationFormsController::class, 'portalIndex']);
        Route::get('association/forms/{form}', [\App\Http\Controllers\Api\AssociationFormsController::class, 'portalShow'])->whereNumber('form');
        Route::post('association/forms/{form}/submit', [\App\Http\Controllers\Api\AssociationFormsController::class, 'submit'])->whereNumber('form');
        Route::post('association/forms/{form}/media', [\App\Http\Controllers\Api\AssociationFormsController::class, 'upload'])->whereNumber('form');
        Route::get('association/media/{upload}', [\App\Http\Controllers\Api\AssociationMediaController::class, 'show'])->whereUuid('upload');
        Route::post('association/forms/{form}/transfers', [\App\Http\Controllers\Api\AssociationTransfersController::class, 'portalStart'])->whereNumber('form');
        Route::get('association/transfers/{transfer}', [\App\Http\Controllers\Api\AssociationTransfersController::class, 'status'])->whereUuid('transfer');
        Route::post('association/transfers/{transfer}/parts/{part}', [\App\Http\Controllers\Api\AssociationTransfersController::class, 'part'])->whereUuid('transfer')->whereNumber('part');
        Route::post('association/transfers/{transfer}/finish', [\App\Http\Controllers\Api\AssociationTransfersController::class, 'finish'])->whereUuid('transfer');
    });
    Route::get('app-content/bootstrap', [Content::class, 'bootstrap']);
    Route::get('app-content/managed', [\App\Http\Controllers\Api\AppWorkspaceController::class, 'publicContent']);
    Route::get('app-content/prepared', [\App\Http\Controllers\Api\PreparedContentController::class, 'index']);
    Route::get('app-content/prepared/{locale}/{kind}', [\App\Http\Controllers\Api\PreparedContentController::class, 'download']);
    Route::get('app-content/releases/{release}', [Content::class, 'release'])->whereNumber('release');
    Route::prefix('admin')->middleware(['auth:sanctum', AppAdminOnly::class])->group(function (): void {
        require __DIR__.'/association_admin.php';
        Route::get('workspace', [\App\Http\Controllers\Api\AppWorkspaceController::class, 'overview']);
        Route::post('workspace/audio/media', \App\Http\Controllers\Api\AppAudioMediaController::class);
        Route::get('workspace/{section}', [\App\Http\Controllers\Api\AppWorkspaceController::class, 'index']);
        Route::post('workspace/{section}', [\App\Http\Controllers\Api\AppWorkspaceController::class, 'save']);
        Route::post('workspace/{section}/{id}/action', [\App\Http\Controllers\Api\AppWorkspaceController::class, 'action']);
        Route::get('languages', [Content::class, 'languages']);
        Route::get('settings', [Content::class, 'settings']);
        Route::put('settings', [Content::class, 'updateSettings']);
        Route::get('languages/{locale}/translations/export', [\App\Http\Controllers\Api\AppTranslationExchangeController::class, 'export']);
        Route::post('languages/{locale}/translations/import', [\App\Http\Controllers\Api\AppTranslationExchangeController::class, 'import']);
        Route::post('languages/{locale}/translations/review', [\App\Http\Controllers\Api\AppTranslationExchangeController::class, 'review']);
        Route::get('languages/{locale}/records', [Content::class, 'records']);
        Route::put('languages/{locale}/records', [Content::class, 'save']);
        Route::post('languages/{locale}/review', [Content::class, 'review']);
        Route::post('languages/{locale}/publish', [Content::class, 'publish']);
        Route::post('languages/{locale}/hide', [Content::class, 'hide']);
        Route::get('languages/{locale}/releases', [Content::class, 'releases']);
        Route::get('languages/{locale}/sources', [Sources::class, 'index']);
        Route::post('languages/{locale}/sources', [Sources::class, 'create']);
        Route::post('languages/{locale}/sources/selection', [Sources::class, 'select']);
        Route::get('languages/{locale}/sources/{id}', [Sources::class, 'preview'])->whereNumber('id');
        Route::post('languages/{locale}/sources/{id}/review', [Sources::class, 'review'])->whereNumber('id');
        Route::get('languages/{locale}/hadith-sources', [HadithSources::class, 'index']);
        Route::post('languages/{locale}/hadith-sources', [HadithSources::class, 'create']);
        Route::post('languages/{locale}/hadith-sources/selection', [HadithSources::class, 'select']);
        Route::get('languages/{locale}/hadith-sources/{id}', [HadithSources::class, 'preview'])->whereNumber('id');
        Route::post('languages/{locale}/hadith-sources/{id}/review', [HadithSources::class, 'review'])->whereNumber('id');
        Route::get('audit', [Content::class, 'audit']);
        Route::get('team', [Content::class, 'team']);
        Route::patch('team/{member}', [Content::class, 'updateMember'])->whereNumber('member');
    });
});
